import java.util.Arrays;

public class Main {
    static int[] reversedCopy(int[] values) {
        int[] copy = Arrays.copyOf(values, values.length);
        for (int left = 0, right = copy.length - 1; left < right; left++, right--) {
            int temp = copy[left]; copy[left] = copy[right]; copy[right] = temp;
        }
        return copy;
    }

    public static void main(String[] args) {
        System.out.println(Arrays.toString(reversedCopy(new int[] {2, 4, 6, 8})));
    }
}

